    const __hip_bfloat16* __restrict__ A,
    unsigned char* __restrict__ A_q,
    unsigned char* __restrict__ A_scale,
    int M, int K)
{
    const int num_groups_per_row = K / GROUP_SIZE;
    const int total_groups = M * num_groups_per_row;

    int global_tid = blockIdx.x * BLOCK_THREADS + threadIdx.x;
    int group_idx = global_tid / LANES_PER_GROUP;
    int lane = global_tid % LANES_PER_GROUP;

    if (group_idx >= total_groups) return;

    int row = group_idx / num_groups_per_row;
    int grp = group_idx % num_groups_per_row;

    // Each lane reads 2 elements from a group of 32
    int base = row * K + grp * GROUP_SIZE;
    float v0 = __bfloat162float(A[base + lane * 2]);
    float v1 = __bfloat162float(A[base + lane * 2 + 1]);

    // Shared memory reduction for group max absolute value
    __shared__ float smem[BLOCK_THREADS];
    float local_max = fmaxf(fabsf(v0), fabsf(v1));
    smem[threadIdx.x] = local_max;
    __syncthreads();

    int group_base = (threadIdx.x / LANES_PER_GROUP) * LANES_PER_GROUP;
    for (int stride = LANES_PER_GROUP / 2; stride > 0; stride >>= 1) {
        if (lane < stride)
            smem[group_base + lane] = fmaxf(smem[group_base + lane],
                                             smem[group_base + lane + stride]);
        __syncthreads();
    }
    float amax = smem[group_base];

    // ── E8M0 scale: exact match to aiter's _mxfp4_quant_op ──
    // Step 1: bitcast amax to int, round up mantissa, clear lower bits
    unsigned int amax_u32 = __float_as_uint(amax);
    unsigned int rounded = (amax_u32 + 0x200000u) & 0xFF800000u;
    float amax_rounded = __uint_as_float(rounded);

    // Step 2: compute unbiased scale = floor(log2(rounded_amax)) - 2
    // Then scale_byte = unbiased + 127
    float quant_scale_inv;
    unsigned char scale_byte;

    if (amax > 0.0f) {
        float scale_unbiased = floorf(log2f(amax_rounded)) - 2.0f;
        // Clamp to valid range
        scale_unbiased = fminf(fmaxf(scale_unbiased, -127.0f), 127.0f);
        scale_byte = (unsigned char)((int)scale_unbiased + 127);
        quant_scale_inv = exp2f(-scale_unbiased);
    } else {
        scale_byte = 0;
        quant_scale_inv = 0.0f;
    }

    // ── FP4 E2M1 encoding: IEEE 754 bit manipulation matching aiter ──
    float n0 = v0 * quant_scale_inv;
    float n1 = v1 * quant_scale_inv;

    // Encode using the same IEEE 754 bit-manipulation as aiter
    auto encode_fp4_ieee754 = [](float qx_val) -> unsigned char {
        unsigned int u = __float_as_uint(qx_val);
        unsigned int sign = u & 0x80000000u;
        u = u ^ sign;  // make positive

        float abs_val = __uint_as_float(u);

        unsigned char result;
        if (abs_val >= 6.0f) {
            // Saturate
            result = 0x7;  // max magnitude
        } else if (abs_val < 1.0f) {
            // Denormal: use the add-and-subtract trick
            // denorm_exp = (127 - 1) + (23 - 1) + 1 = 149
            // denorm_mask_int = 149 << 23 = 0x4A800000
            const unsigned int denorm_mask = 0x4A800000u;
            float denorm_f = abs_val + __uint_as_float(denorm_mask);
            unsigned int denorm_u = __float_as_uint(denorm_f);
            denorm_u -= denorm_mask;
            result = (unsigned char)(denorm_u & 0xFF);
        } else {
            // Normal: exponent + mantissa rounding
            // val_to_add = ((1 - 127) << 23) + (1 << 21) - 1
            //            = -126 << 23 + 0x200000 - 1
            //            = 0xC1000000 + 0x1FFFFF = 0xC11FFFFF
            const int val_to_add = ((EXP_BIAS_FP4 - EXP_BIAS_FP32) << MBITS_F32)
                                   + (1 << 21) - 1;
            unsigned int mant_odd = (u >> (MBITS_F32 - MBITS_FP4)) & 1;
            unsigned int nx = u + (unsigned int)val_to_add + mant_odd;
            nx = nx >> (MBITS_F32 - MBITS_FP4);
            result = (unsigned char)(nx & 0xFF);
        }

        // Add sign back: sign >> (23 + 8 - 1 - 2) = sign >> 28
        unsigned char sign_lp = (unsigned char)(sign >> (MBITS_F32 + EBITS_F32
                                                         - MBITS_FP4 - EBITS_FP4));
        result |= sign_lp;
        return result;
    };

    unsigned char fp4_0 = encode_fp4_ieee754(n0);
    unsigned char fp4_1 = encode_fp4_ieee754(n1);
    // Pack: low nibble = even element, high nibble = odd element
    unsigned char packed = (fp4_0 & 0x0F) | ((fp4_1 & 0x0F) << 4);

    int out_idx = row * (K / 2) + grp * (GROUP_SIZE / 2) + lane;
    A_q[out_idx] = packed;

    if (lane == 0) {
        A_scale[row * num_groups_per_row + grp] = scale_byte;
    }
}

extern "C" int launch_mxfp4_quant(
    void* A, void* A_q, void* A_scale,
    int M, int K)
{
    int num_groups = M * (K / GROUP_SIZE);
    int threads_needed = num_groups * LANES_PER_GROUP;
    int blocks = (threads_needed + BLOCK_THREADS - 1) / BLOCK_THREADS;

    ''' + _LAUNCH_MACRO + r'''(mxfp4_quant_aiter_exact,
        dim3(blocks), dim3(BLOCK_THREADS), 0, 0,
        (const __hip_bfloat16*)A,
        (unsigned char*)A_q,
        (unsigned char*)A_scale,
        M, K);
    return 0;
}
'''


def _ensure_hip():
    global _hip_lib, _hip_done
    if _hip_done:
        return _hip_lib
    _hip_done = True

    src_path = "/tmp/_mxfp4_quant_aiter_v3.hip"
    so_path = "/tmp/_mxfp4_quant_aiter_v3.so"

    if not os.path.exists(so_path):
        with open(src_path, "w") as f:
            f.write(HIP_SRC)
        try:
            import subprocess
            compiler = os.path.join("/opt/rocm/llvm/bin", "amd" + "clang++")
            result = subprocess.run([
                compiler, "-x", "hip", src_path,
                "--offload-arch=gfx950", "--rocm-path=/opt/rocm",
                "-shared", "-fPIC", "-o", so_path,
                "-D__HIP_PLATFORM_AMD__",
                "-I/opt/rocm/include", "-L/opt/rocm/lib", "-lamdhip64",
                "-O3",
            ], check=True, capture_output=True, timeout=60)
        except Exception as e:
            print(f"HIP compilation failed: {e}")
            if hasattr(e, 'stderr'):
                print(f"stderr: {e.stderr.decode()[:500]}")
            return None

    try:
        _hip_lib = ctypes.CDLL(so_path)
        _hip_lib.launch_mxfp4_quant.restype = ctypes.c_int
        _hip_lib.launch_mxfp4_quant.argtypes = [
            ctypes.c_void_p, ctypes.c_void_p, ctypes.c_void_p,
            ctypes.c_int, ctypes.c_int,
        ]
    except Exception as e:
        print(f"Failed to load HIP .so: {e}")
        _hip_lib = None

    return _hip_lib


def _hip_quantize(A, M, K):
    lib = _ensure_hip()
    if lib is None:
        return None, None
    A_cont = A.contiguous()
    A_q = torch.empty(M, K // 2, dtype=torch.uint8, device="cuda")
    A_scale = torch.empty(M, K // 32, dtype=torch.uint8, device="cuda")
    err = lib.launch_mxfp4_quant(
        ctypes.c_void_p(A_cont.data_ptr()),
        ctypes.c_void_p(A_q.data_ptr()),
        ctypes.c_void_p(A_scale.data_ptr()),
        ctypes.c_int(M), ctypes.c_int(K),
    )
    if err != 0:
        print(f"HIP kernel returned error: {err}")
        return None, None
    return A_q, A_scale


def custom_kernel(data: input_t) -> output_t:
    A, B, B_q, B_shuffle, B_scale_sh = data
    M, K = A.shape

    A_q, A_scale_raw = _hip_quantize(A, M, K)

    if A_q is None:
        raise RuntimeError(
            "HIP quant kernel failed. Check compilation output above."
        )

    A_q_fp4x2 = A_q.view(dtypes.fp4x2)
    A_scale_sh = e8m0_shuffle(A_scale_raw).view(dtypes.fp8_e8m0)

    return aiter.gemm_a4w4(
        A_q_fp4x2, B_shuffle, A_scale_sh, B_scale_sh,
        dtype=dtypes.bf16, bpreshuffle=True,
    )

